    int t = n + k + 1;
    n_ = n * t + 1;
    m_ = 0;
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s;
            for (Link *l = aa[i].next; l; l = l->next) {
