import java.util.*;
import java.io.*;

public class Main {
    static final int N = 50, M = 50, K = 50;
    static int N_ = N * (N + K + 1) + 1;
    static int M_ = K + (M * 2 * K + N) * (N + K);
    static final int INF = 0x3f3f3f3f;
    static int[] pi = new int[N_], kk = new int[N_], bb = new int[N_];
    static int[] pq = new int[1 + N_], iq = new int[N_], cnt = 0;

    static int i2(int i) {
        i <<= 1;
        if (i > cnt[0]) return 0;
        if (i < cnt[0] && (pi[pq[i + 1]] < pi[pq[i]] || (pi[pq[i + 1]] == pi[pq[i]] && kk[pq[i + 1]] < kk[pq[i]]))) return i + 1;
        return i;
    }

    static void pushUp(int u) {
        int i = iq[u], j;
        while (i > 1 && (pi[u] < pi[pq[j = i / 2]] || (pi[u] == pi[pq[j]] && kk[u] < kk[pq[j]]))) {
            pq[iq[pq[j]] = i] = pq[j];
            i = j;
        }
        pq[iq[u] = i] = u;
    }

    static void pushDown(int u) {
        int i = iq[u], j;
        while ((j = i2(i)) != 0 && (pi[pq[j]] < pi[u] || (pi[pq[j]] == pi[u] && kk[pq[j]] < kk[u]))) {
            pq[iq[pq[j]] = i] = pq[j];
            i = j;
        }
        pq[iq[u] = i] = u;
    }

    static void enqueue(int u) {
        iq[u] = ++cnt[0];
        pushUp(u);
    }

    static int dequeue() {
        int u = pq[1], v = pq[cnt[0]--];
        iq[v] = 1;
        pushDown(v);
        return u;
    }

    static class Link {
        Link next;
        int j;
        public Link() {
            next = null;
        }
    }

    static Link[] aa = new Link[N], aa_ = new Link[N_];

    static class Edge {
        int u, v, cap, cost, revU, revV;
        public Edge(int u, int v, int cap, int cost, int revU, int revV) {
            this.u = u; this.v = v; this.cap = cap; this.cost = cost; this.revU = revU; this.revV = revV;
        }
    }

    static List<Edge>[] graph;
    static int n_, m_;
    static int[] uu = new int[M_], vv = new int[M_], uv = new int[M_], cost = new int[M_], cost_ = new int[M_];
    static int[] cc = new int[M_ * 2];

    static void addEdge(int i, int j, int cap, int cos) {
        if (graph == null || graph.length == 0) {
            graph = new ArrayList[ N_ + M_ * 2];
            for (int z = 0; z < graph.length; z++) graph[z] = new ArrayList<>();
        }
        int h = m_++;
        uu[h] = i; vv[h] = j; uv[h] = i ^ j; cost[h] = cos;
        graph[i].add(new Edge(i, j, cap, cos, h, h));
        graph[j].add(new Edge(j, i, 0, -cos, h, h));
    }

    static void dijkstra(int s) {
        Arrays.fill(pi, 0, n_, INF);
        pi[s] = 0;
        cnt[0] = 0;
        enqueue(s);
        while (cnt[0] != 0) {
            int u = dequeue();
            for (Edge e : graph[u]) {
                int h_ = e.revU, v = e.v;
                if (e.cap > 0) {
                    int p = pi[u] + e.cost;
                    if (pi[v] == INF) {
                        pi[v] = p;
                        kk[v] = kk[u] + 1;
                        bb[v] = h_;
                        enqueue(v);
                    } else if (pi[v] > p || (pi[v] == p && kk[v] > kk[u] + 1)) {
                        pi[v] = p;
                        kk[v] = kk[u] + 1;
                        bb[v] = h_;
                        pushUp(v);
                    }
                }
            }
        }
    }

    static void relabel(int s, int t) {
        for (int u = t; u != s; u ^= uv[bb[u]]) {
            int h_ = bb[u], h = h_ >> 1;
            cc[h_ ^ 1]--;
            cc[h_]++;
        }
    }

    static int max_flow(int s, int t) {
        System.arraycopy(cost, 0, cost_, 0, m_);
        while (true) {
            dijkstra(s);
            if (pi[t] == INF) break;
            relabel(s, t);
            for (int h = 0; h < m_; h++) {
                int u = uu[h], v = vv[h];
                if (pi[u] != INF && pi[v] != INF) {
                    cost_[h] += pi[u] - pi[v];
                }
            }
        }
        int total = 0;
        for (int h = 0; h < m_; h++) {
            total += cost[h] * cc[h << 1 ^ 1];
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] ii = new int[K];
        int n, m, k, c, d;
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();
        for (int h = 0; h < k; h++) {
            ii[h] = sc.nextInt() - 1;
        }
        for (int h = 0; h < m; h++) {
            int i = sc.nextInt() - 1;
            int j = sc.nextInt() - 1;
            addEdge(i, j, 1, 0);
            addEdge(j, i, 1, 0);
        }
        int t = n + k + 1;
        n_ = n * t + 1;
        m_ = 0;
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (Link l = aa[i]; l != null; l = l.next) {
                    int j = l.j;
                    int v = j * t + s + 1;
                    for (int x = 1; x <= k; x++) {
                        addEdge(u, v, 1, c + (x * 2 - 1) * d);
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s, v = u + 1;
                addEdge(u, v, k, i == 0 ? 0 : c);
            }
        }
        for (int h = 0; h < k; h++) {
            addEdge(n_ - 1, ii[h] * t, 1, 0);
        }
        System.out.println(max_flow(n_ - 1, 0 * t + t - 1));
    }
}

